    public int countSquares(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int count = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int maxK = Math.min(m - r, n - c);
                for (int k = 1; k <= maxK; k++) {
                    boolean ok = true;
                    for (int dr = 0; dr < k && ok; dr++) {
                        for (int dc = 0; dc < k && ok; dc++) {
                            if (matrix[r + dr][c + dc] == 0) ok = false;
                        }
                    }
                    if (ok) count++;
                    else break;
                }
            }
        }
        return count;
    }
}

