    public int cherryPickup(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        return dfs(grid, 0, 0, n - 1);
    }
    private int dfs(int[][] grid, int r, int c1, int c2) {
        int m = grid.length, n = grid[0].length;
        if (c1 < 0 || c1 >= n || c2 < 0 || c2 >= n) return -1_000_000;
        int cherries = grid[r][c1] + (c1 != c2 ? grid[r][c2] : 0);
        if (r == m - 1) return cherries;
        int maxNext = -1_000_000;
        for (int dc1 = -1; dc1 <= 1; dc1++) {
            for (int dc2 = -1; dc2 <= 1; dc2++) {
                maxNext = Math.max(maxNext, dfs(grid, r + 1, c1 + dc1, c2 + dc2));
            }
        }
        return cherries + maxNext;
    }
}

