class Solution {
    public int cherryPickup(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dp = new int[n][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        dp[0][n - 1] = grid[0][0] + (n > 1 ? grid[0][n - 1] : 0);
        for (int r = 1; r < m; r++) {
            int[][] nextDp = new int[n][n];
            for (int[] row : nextDp) Arrays.fill(row, -1);
            for (int c1 = 0; c1 < n; c1++) {
                for (int c2 = 0; c2 < n; c2++) {
                    if (dp[c1][c2] < 0) continue;
                    for (int dc1 = -1; dc1 <= 1; dc1++) {
                        for (int dc2 = -1; dc2 <= 1; dc2++) {
                            int nc1 = c1 + dc1, nc2 = c2 + dc2;
                            if (nc1 >= 0 && nc1 < n && nc2 >= 0 && nc2 < n) {
                                int gain = grid[r][nc1] + (nc1 != nc2 ? grid[r][nc2] : 0);
                                nextDp[nc1][nc2] = Math.max(nextDp[nc1][nc2], dp[c1][c2] + gain);
                            }
                        }
                    }
                }
            }
            dp = nextDp;
        }
        int maxCherries = 0;
        for (int c1 = 0; c1 < n; c1++) {
            for (int c2 = 0; c2 < n; c2++) {
                maxCherries = Math.max(maxCherries, dp[c1][c2]);
            }
        }
        return maxCherries;
    }
}

