class Solution {
    public int minimumDeleteSum(String s1, String s2) {
        return dfs(s1, s2, s1.length(), s2.length());
    }
    private int dfs(String s1, String s2, int i, int j) {
        if (i == 0) {
            int sum = 0;
            for (int k = 0; k < j; k++) sum += s2.charAt(k);
            return sum;
        }
        if (j == 0) {
            int sum = 0;
            for (int k = 0; k < i; k++) sum += s1.charAt(k);
            return sum;
        }
        if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
            return dfs(s1, s2, i - 1, j - 1);
        }
        int del1 = dfs(s1, s2, i - 1, j) + (int) s1.charAt(i - 1);
        int del2 = dfs(s1, s2, i, j - 1) + (int) s2.charAt(j - 1);
        return Math.min(del1, del2);
    }
}

