    private String dfs(String s1, String s2, int i, int j) {
        if (i == s1.length()) return s2.substring(j);
        if (j == s2.length()) return s1.substring(i);
        if (s1.charAt(i) == s2.charAt(j)) {
            return s1.charAt(i) + dfs(s1, s2, i + 1, j + 1);
        }
        String opt1 = s1.charAt(i) + dfs(s1, s2, i + 1, j);
        String opt2 = s2.charAt(j) + dfs(s1, s2, i, j + 1);
        return opt1.length() <= opt2.length() ? opt1 : opt2;
    }
