class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffixSum = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixSum[i] = suffixSum[i + 1] + piles[i];
        }
        return dfs(piles, suffixSum, 0, 1);
    }
    private int dfs(int[] piles, int[] suffixSum, int i, int M) {
        int n = piles.length;
        if (i + 2 * M >= n) return suffixSum[i];
        int maxStones = 0;
        for (int X = 1; X <= 2 * M; X++) {
            int stones = suffixSum[i] - dfs(piles, suffixSum, i + X, Math.max(M, X));
            maxStones = Math.max(maxStones, stones);
        }
        return maxStones;
    }
}

