class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffixSum = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixSum[i] = suffixSum[i + 1] + piles[i];
        }
        int[][] memo = new int[n][n + 1];
        return dfs(piles, suffixSum, memo, 0, 1);
    }
    private int dfs(int[] piles, int[] suffixSum, int[][] memo, int i, int M) {
        int n = piles.length;
        if (i >= n) return 0;
        if (i + 2 * M >= n) return suffixSum[i];
        if (memo[i][M] != 0) return memo[i][M];
        int best = 0;
        for (int X = 1; X <= 2 * M; X++) {
            int stones = suffixSum[i] - dfs(piles, suffixSum, memo, i + X, Math.max(M, X));
            best = Math.max(best, stones);
        }
        return memo[i][M] = best;
    }
}

