            int maxLeft = 0, maxRight = 0;
            for (int p = i; p <= k; p++) maxLeft = Math.max(maxLeft, arr[p]);
            for (int p = k + 1; p <= j; p++) maxRight = Math.max(maxRight, arr[p]);
            int cost = maxLeft * maxRight + dfs(arr, i, k) + dfs(arr, k + 1, j);
            minCost = Math.min(minCost, cost);
        }
        return minCost;
    }
}

