class Solution {
    public int mctFromLeafValues(int[] arr) {
        int total = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(Integer.MAX_VALUE);
        for (int x : arr) {
            while (stack.peek() <= x) {
                int mid = stack.pop();
                total += mid * Math.min(stack.peek(), x);
            }
            stack.push(x);
        }
        while (stack.size() > 2) {
            int mid = stack.pop();
            total += mid * stack.peek();
        }
        return total;
    }
}

