            for (int i = 0; i <= m + 1 - diff; i++) {
                int j = i + diff;
                int minVal = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {
                    minVal = Math.min(minVal, dp[i][k] + dp[k][j]);
